python3 - <<'PY'
g=[[9,9,9,9,4,9,4,4,4,9,4,4,4,9,4,4,9,9,4],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],[9]*19,[9,9,9,9,4,9,4,4,4,4,9,9,4,4,4,4,4,4,4],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,9],[9,9,9,9,4,9,9,9,9,9,9,9,9,9,9,9,9,9,4],[9,9,9,9,4,4,9,4,9,4,4,9,9,4,9,4,9,4,4]]
# color 2 gaps in each row/col between consecutive same-color marks? all 4 cells form edges, gaps between mark endpoints on rows/columns
R,C=7,19
for i in range(R):
 js=[j for j in range(C) if g[i][j]==4]
 for a,b in zip(js,js[1:]):
  for j in range(a+1,b):
   if g[i][j]==9:g[i][j]=2
for j in range(C):
 ii=[i for i in range(R) if g[i][j]==4]
 for a,b in zip(ii,ii[1:]):
  for i in range(a+1,b):
   if g[i][j]==9:g[i][j]=2
for r in g:print(r)
PY

